51	
52	namespace aria2 {
53	
54	DHTBucket::DHTBucket(size_t prefixLength, const unsigned char* max,
55	                     const unsigned char* min,
56	                     const std::shared_ptr<DHTNode>& localNode)
57	    : prefixLength_(prefixLength),
58	      localNode_(localNode),
59	      lastUpdated_(global::wallclock())
60	{
61	  memcpy(max_, max, DHT_ID_LENGTH);
62	  memcpy(min_, min, DHT_ID_LENGTH);
63	}
64	
65	DHTBucket::DHTBucket(const std::shared_ptr<DHTNode>& localNode)
66	    : prefixLength_(0), localNode_(localNode), lastUpdated_(global::wallclock())
67	{
68	  memset(max_, 0xffu, DHT_ID_LENGTH);
69	  memset(min_, 0, DHT_ID_LENGTH);
70	}
71	
72	DHTBucket::~DHTBucket() = default;
73	
74	void DHTBucket::getRandomNodeID(unsigned char* nodeID) const
75	{
76	  if (prefixLength_ == 0) {
77	    util::generateRandomKey(nodeID);
78	  }
79	  else {
80	    size_t lastByteIndex = (prefixLength_ - 1) / 8;
81	    util::generateRandomKey(nodeID);
82	    memcpy(nodeID, min_, lastByteIndex + 1);
83	  }
84	}
85	
86	bool DHTBucket::isInRange(const std::shared_ptr<DHTNode>& node) const
87	{
88	  return isInRange(node->getID(), max_, min_);
89	}
90	
91	bool DHTBucket::isInRange(const unsigned char* nodeID) const
92	{
93	  return isInRange(nodeID, max_, min_);
94	}
95	
96	// Returns true if nodeID is in [min, max] (inclusive).
97	bool DHTBucket::isInRange(const unsigned char* nodeID, const unsigned char* max,
98	                          const unsigned char* min) const
99	{
100	  return !std::lexicographical_compare(&nodeID[0], &nodeID[DHT_ID_LENGTH],
101	                                       &min[0], &min[DHT_ID_LENGTH]) &&
102	         !std::lexicographical_compare(&max[0], &max[DHT_ID_LENGTH], &nodeID[0],
103	                                       &nodeID[DHT_ID_LENGTH]);
104	}
105	
106	bool DHTBucket::addNode(const std::shared_ptr<DHTNode>& node)
107	{
108	  notifyUpdate();
109	  auto itr = std::find_if(nodes_.begin(), nodes_.end(), derefEqual(node));
110	  if (itr == nodes_.end()) {
111	    if (nodes_.size() < K) {
112	      nodes_.push_back(node);
113	      return true;
114	    }
115	    else {
116	      if (nodes_.front()->isBad()) {
117	        nodes_.erase(nodes_.begin());
118	        nodes_.push_back(node);
119	        return true;
120	      }
121	      else {
122	        return false;
123	      }
124	    }
125	  }
126	  else {
127	    nodes_.erase(itr);
128	    nodes_.push_back(node);
129	    return true;
130	  }
131	}
132	
133	void DHTBucket::cacheNode(const std::shared_ptr<DHTNode>& node)
134	{
135	  // cachedNodes_ are sorted by last time seen
136	  cachedNodes_.push_front(node);
137	  if (cachedNodes_.size() > CACHE_SIZE) {
138	    cachedNodes_.resize(CACHE_SIZE, std::shared_ptr<DHTNode>());
139	  }
140	}
141	
142	void DHTBucket::dropNode(const std::shared_ptr<DHTNode>& node)
143	{
144	  if (!cachedNodes_.empty()) {
145	    auto itr = std::find_if(nodes_.begin(), nodes_.end(), derefEqual(node));
146	    if (itr != nodes_.end()) {
147	      nodes_.erase(itr);
148	      nodes_.push_back(cachedNodes_.front());
149	      cachedNodes_.erase(cachedNodes_.begin());
150	    }
151	  }
152	}
153	
154	void DHTBucket::moveToHead(const std::shared_ptr<DHTNode>& node)
155	{
156	  auto itr = std::find_if(nodes_.begin(), nodes_.end(), derefEqual(node));
157	  if (itr != nodes_.end()) {
158	    nodes_.erase(itr);
159	    nodes_.push_front(node);
160	  }
161	}
162	
163	void DHTBucket::moveToTail(const std::shared_ptr<DHTNode>& node)
164	{
165	  auto itr = std::find_if(nodes_.begin(), nodes_.end(), derefEqual(node));
166	  if (itr != nodes_.end()) {
167	    nodes_.erase(itr);
168	    nodes_.push_back(node);
169	  }
170	}
171	
172	bool DHTBucket::splitAllowed() const
173	{
174	  return prefixLength_ < DHT_ID_LENGTH * 8 - 1 && isInRange(localNode_);
175	}
176	
177	std::unique_ptr<DHTBucket> DHTBucket::split()
178	{
179	  assert(splitAllowed());
180	
181	  unsigned char rMax[DHT_ID_LENGTH];
182	  memcpy(rMax, max_, DHT_ID_LENGTH);
183	  bitfield::flipBit(rMax, DHT_ID_LENGTH, prefixLength_);
184	  unsigned char rMin[DHT_ID_LENGTH];
185	  memcpy(rMin, min_, DHT_ID_LENGTH);
186	
187	  bitfield::flipBit(min_, DHT_ID_LENGTH, prefixLength_);
188	
189	  ++prefixLength_;
190	  auto rBucket = make_unique<DHTBucket>(prefixLength_, rMax, rMin, localNode_);
191	
192	  std::deque<std::shared_ptr<DHTNode>> lNodes;
193	  for (auto& elem : nodes_) {
194	    if (rBucket->isInRange(elem)) {
195	      assert(rBucket->addNode(elem));
196	    }
197	    else {
198	      lNodes.push_back(elem);
199	    }
200	  }
201	  nodes_ = lNodes;
202	  // TODO create toString() and use it.
203	  A2_LOG_DEBUG(fmt("New bucket. prefixLength=%u, Range:%s-%s",
204	                   static_cast<unsigned int>(rBucket->getPrefixLength()),
205	                   util::toHex(rBucket->getMinID(), DHT_ID_LENGTH).c_str(),
206	                   util::toHex(rBucket->getMaxID(), DHT_ID_LENGTH).c_str()));
207	  A2_LOG_DEBUG(fmt("Existing bucket. prefixLength=%u, Range:%s-%s",
208	                   static_cast<unsigned int>(prefixLength_),
209	                   util::toHex(getMinID(), DHT_ID_LENGTH).c_str(),
210	                   util::toHex(getMaxID(), DHT_ID_LENGTH).c_str()));
211	  return rBucket;
212	}
213	
214	void DHTBucket::getGoodNodes(
215	    std::vector<std::shared_ptr<DHTNode>>& goodNodes) const
216	{
217	  goodNodes.insert(goodNodes.end(), nodes_.begin(), nodes_.end());
218	  goodNodes.erase(std::remove_if(goodNodes.begin(), goodNodes.end(),
219	                                 std::mem_fn(&DHTNode::isBad)),
220	                  goodNodes.end());
221	}
222	
223	std::shared_ptr<DHTNode> DHTBucket::getNode(const unsigned char* nodeID,
224	                                            const std::string& ipaddr,
225	                                            uint16_t port) const
226	{
227	  auto node = std::make_shared<DHTNode>(nodeID);
228	  node->setIPAddress(ipaddr);
229	  node->setPort(port);
230	  auto itr = std::find_if(nodes_.begin(), nodes_.end(), derefEqual(node));
231	  if (itr == nodes_.end() || (*itr)->getIPAddress() != ipaddr ||
232	      (*itr)->getPort() != port) {
233	    return nullptr;
234	  }
235	  else {
236	    return *itr;
237	  }
238	}
239	
240	bool DHTBucket::operator==(const DHTBucket& bucket) const
241	{
242	  return memcmp(max_, bucket.max_, DHT_ID_LENGTH) == 0 &&
243	         memcmp(min_, bucket.min_, DHT_ID_LENGTH) == 0;
244	}
245	
246	bool DHTBucket::needsRefresh() const
247	{
248	  return nodes_.size() < K || lastUpdated_.difference(global::wallclock()) >=
249	                                  DHT_BUCKET_REFRESH_INTERVAL;
250	}
251	
252	void DHTBucket::notifyUpdate() { lastUpdated_ = global::wallclock(); }
