151	  }
152	}
153	
154	void DHTBucket::moveToHead(const std::shared_ptr<DHTNode>& node)
155	{
156	  auto itr = std::find_if(nodes_.begin(), nodes_.end(), derefEqual(node));
157	  if (itr != nodes_.end()) {
158	    nodes_.erase(itr);
159	    nodes_.push_front(node);
160	  }
161	}
162	
163	void DHTBucket::moveToTail(const std::shared_ptr<DHTNode>& node)
164	{
165	  auto itr = std::find_if(nodes_.begin(), nodes_.end(), derefEqual(node));
166	  if (itr != nodes_.end()) {
167	    nodes_.erase(itr);
168	    nodes_.push_back(node);
169	  }
170	}
171	
172	bool DHTBucket::splitAllowed() const
173	{
174	  return prefixLength_ < DHT_ID_LENGTH * 8 - 1 && isInRange(localNode_);
175	}
176	
177	std::unique_ptr<DHTBucket> DHTBucket::split()
178	{
179	  assert(splitAllowed());
180	
181	  unsigned char rMax[DHT_ID_LENGTH];
182	  memcpy(rMax, max_, DHT_ID_LENGTH);
183	  bitfield::flipBit(rMax, DHT_ID_LENGTH, prefixLength_);
184	  unsigned char rMin[DHT_ID_LENGTH];
185	  memcpy(rMin, min_, DHT_ID_LENGTH);
186	
187	  bitfield::flipBit(min_, DHT_ID_LENGTH, prefixLength_);
188	
189	  ++prefixLength_;
190	  auto rBucket = make_unique<DHTBucket>(prefixLength_, rMax, rMin, localNode_);
191	
192	  std::deque<std::shared_ptr<DHTNode>> lNodes;
193	  for (auto& elem : nodes_) {
194	    if (rBucket->isInRange(elem)) {
195	      assert(rBucket->addNode(elem));
196	    }
197	    else {
198	      lNodes.push_back(elem);
199	    }
200	  }
201	  nodes_ = lNodes;
202	  // TODO create toString() and use it.
203	  A2_LOG_DEBUG(fmt("New bucket. prefixLength=%u, Range:%s-%s",
204	                   static_cast<unsigned int>(rBucket->getPrefixLength()),
205	                   util::toHex(rBucket->getMinID(), DHT_ID_LENGTH).c_str(),
206	                   util::toHex(rBucket->getMaxID(), DHT_ID_LENGTH).c_str()));
207	  A2_LOG_DEBUG(fmt("Existing bucket. prefixLength=%u, Range:%s-%s",
208	                   static_cast<unsigned int>(prefixLength_),
209	                   util::toHex(getMinID(), DHT_ID_LENGTH).c_str(),
210	                   util::toHex(getMaxID(), DHT_ID_LENGTH).c_str()));
211	  return rBucket;
212	}
213	
214	void DHTBucket::getGoodNodes(
215	    std::vector<std::shared_ptr<DHTNode>>& goodNodes) const
216	{
217	  goodNodes.insert(goodNodes.end(), nodes_.begin(), nodes_.end());
218	  goodNodes.erase(std::remove_if(goodNodes.begin(), goodNodes.end(),
219	                                 std::mem_fn(&DHTNode::isBad)),
220	                  goodNodes.end());
221	}
222	
223	std::shared_ptr<DHTNode> DHTBucket::getNode(const unsigned char* nodeID,
224	                                            const std::string& ipaddr,
225	                                            uint16_t port) const
226	{
227	  auto node = std::make_shared<DHTNode>(nodeID);
228	  node->setIPAddress(ipaddr);
229	  node->setPort(port);
230	  auto itr = std::find_if(nodes_.begin(), nodes_.end(), derefEqual(node));
231	  if (itr == nodes_.end() || (*itr)->getIPAddress() != ipaddr ||
232	      (*itr)->getPort() != port) {
233	    return nullptr;
234	  }
235	  else {
236	    return *itr;
237	  }
238	}
239	
240	bool DHTBucket::operator==(const DHTBucket& bucket) const
241	{
242	  return memcmp(max_, bucket.max_, DHT_ID_LENGTH) == 0 &&
243	         memcmp(min_, bucket.min_, DHT_ID_LENGTH) == 0;
244	}
245	
246	bool DHTBucket::needsRefresh() const
247	{
248	  return nodes_.size() < K || lastUpdated_.difference(global::wallclock()) >=
249	                                  DHT_BUCKET_REFRESH_INTERVAL;
250	}
251	
252	void DHTBucket::notifyUpdate() { lastUpdated_ = global::wallclock(); }
253	
254	namespace {
255	class FindQuestionableNode {
256	public:
257	  bool operator()(const std::shared_ptr<DHTNode>& node) const
258	  {
259	    return node->isQuestionable();
260	  }
261	};
262	} // namespace
263	
264	bool DHTBucket::containsQuestionableNode() const
265	{
266	  return std::find_if(nodes_.begin(), nodes_.end(), FindQuestionableNode()) !=
267	         nodes_.end();
268	}
269	
270	std::shared_ptr<DHTNode> DHTBucket::getLRUQuestionableNode() const
271	{
272	  auto i = std::find_if(nodes_.begin(), nodes_.end(), FindQuestionableNode());
273	  if (i == nodes_.end()) {
274	    return nullptr;
275	  }
276	  else {
277	    return *i;
278	  }
279	}
