120	void collectNodes(std::vector<std::shared_ptr<DHTNode>>& nodes,
121	                  const std::shared_ptr<DHTBucket>& bucket)
122	{
123	  std::vector<std::shared_ptr<DHTNode>> goodNodes;
124	  bucket->getGoodNodes(goodNodes);
125	  nodes.insert(nodes.end(), goodNodes.begin(), goodNodes.end());
126	}
