130	void collectDownwardLeftFirst(std::vector<std::shared_ptr<DHTNode>>& nodes,
131	                              DHTBucketTreeNode* tnode)
132	{
133	  if (tnode->leaf()) {
134	    collectNodes(nodes, tnode->getBucket());
135	  }
136	  else {
137	    collectDownwardLeftFirst(nodes, tnode->getLeft());
138	    if (nodes.size() < DHTBucket::K) {
139	      collectDownwardLeftFirst(nodes, tnode->getRight());
140	    }
141	  }
142	}
143	} // namespace
