74	bool DHTRoutingTable::addNode(const std::shared_ptr<DHTNode>& node, bool good)
75	{
76	  A2_LOG_DEBUG(fmt("Trying to add node:%s", node->toString().c_str()));
77	  if (*localNode_ == *node) {
78	    A2_LOG_DEBUG("Adding node with the same ID with localnode is not allowed.");
79	    return false;
80	  }
81	  auto treeNode = dht::findTreeNodeFor(root_.get(), node->getID());
82	  while (1) {
83	    const std::shared_ptr<DHTBucket>& bucket = treeNode->getBucket();
84	    if (bucket->addNode(node)) {
85	      A2_LOG_DEBUG("Added DHTNode.");
86	      return true;
87	    }
88	    else if (bucket->splitAllowed()) {
89	      A2_LOG_DEBUG(fmt("Splitting bucket. Range:%s-%s",
90	                       util::toHex(bucket->getMinID(), DHT_ID_LENGTH).c_str(),
91	                       util::toHex(bucket->getMaxID(), DHT_ID_LENGTH).c_str()));
92	      treeNode->split();
93	      ++numBucket_;
94	      if (treeNode->getLeft()->isInRange(node->getID())) {
95	        treeNode = treeNode->getLeft();
96	      }
97	      else {
98	        treeNode = treeNode->getRight();
99	      }
100	    }
101	    else {
102	      if (good) {
103	        bucket->cacheNode(node);
104	        A2_LOG_DEBUG(fmt("Cached node=%s", node->toString().c_str()));
105	      }
106	      return false;
107	    }
108	  }
109	  return false;
110	}
