49	
50	// Returns the bit mask for the last byte. For example, nbits = 9,
51	// then 0x80u is returned. nbits = 12, then 0xf0u is returned.
52	inline unsigned char lastByteMask(size_t nbits)
53	{
54	  if (nbits == 0) {
55	    return 0;
56	  }
57	  else {
58	    int s = nbits % 8;
59	    if (s == 0) {
60	      return 0xffu;
61	    }
62	    else {
63	      return -256 >> s;
64	    }
65	  }
66	}
67	
68	// Returns true if index-th bits is set. Otherwise returns false.
69	template <typename Array>
70	inline bool test(const Array& bitfield, size_t nbits, size_t index)
71	{
72	  assert(index < nbits);
73	  unsigned char mask = 128 >> (index % 8);
74	  return (bitfield[index / 8] & mask) != 0;
75	}
76	
77	const int cntbits[] = {
78	    0, 1, 1, 2, 1, 2, 2, 3, 1, 2, 2, 3, 2, 3, 3, 4, 1, 2, 2, 3, 2, 3, 3, 4,
79	    2, 3, 3, 4, 3, 4, 4, 5, 1, 2, 2, 3, 2, 3, 3, 4, 2, 3, 3, 4, 3, 4, 4, 5,
80	    2, 3, 3, 4, 3, 4, 4, 5, 3, 4, 4, 5, 4, 5, 5, 6, 1, 2, 2, 3, 2, 3, 3, 4,
81	    2, 3, 3, 4, 3, 4, 4, 5, 2, 3, 3, 4, 3, 4, 4, 5, 3, 4, 4, 5, 4, 5, 5, 6,
82	    2, 3, 3, 4, 3, 4, 4, 5, 3, 4, 4, 5, 4, 5, 5, 6, 3, 4, 4, 5, 4, 5, 5, 6,
83	    4, 5, 5, 6, 5, 6, 6, 7, 1, 2, 2, 3, 2, 3, 3, 4, 2, 3, 3, 4, 3, 4, 4, 5,
84	    2, 3, 3, 4, 3, 4, 4, 5, 3, 4, 4, 5, 4, 5, 5, 6, 2, 3, 3, 4, 3, 4, 4, 5,
85	    3, 4, 4, 5, 4, 5, 5, 6, 3, 4, 4, 5, 4, 5, 5, 6, 4, 5, 5, 6, 5, 6, 6, 7,
86	    2, 3, 3, 4, 3, 4, 4, 5, 3, 4, 4, 5, 4, 5, 5, 6, 3, 4, 4, 5, 4, 5, 5, 6,
87	    4, 5, 5, 6, 5, 6, 6, 7, 3, 4, 4, 5, 4, 5, 5, 6, 4, 5, 5, 6, 5, 6, 6, 7,
