91	inline size_t countBit32(uint32_t n)
92	{
93	  return cntbits[n & 0xffu] + cntbits[(n >> 8) & 0xffu] +
94	         cntbits[(n >> 16) & 0xffu] + cntbits[(n >> 24) & 0xffu];
95	}
96	
97	// Counts set bit in bitfield.
98	inline size_t countSetBit(const unsigned char* bitfield, size_t nbits)
99	{
100	  if (nbits == 0) {
101	    return 0;
102	  }
103	  size_t count = 0;
104	  size_t size = sizeof(uint32_t);
105	  size_t len = (nbits + 7) / 8;
106	  if (nbits % 32 != 0) {
107	    --len;
108	    count +=
109	        countBit32(static_cast<uint32_t>(bitfield[len] & lastByteMask(nbits)));
110	  }
111	  size_t to = len / size;
112	  for (size_t i = 0; i < to; ++i) {
113	    uint32_t v;
114	    memcpy(&v, &bitfield[i * size], sizeof(v));
115	    count += countBit32(v);
